                    datasets: [
                        { data: state.domainState.retentionHistory },
                        { data: state.domainState.fairnessHistory },
                        { data: state.domainState.satisfactionHistory }
                    ]
                },
                budgetChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.budgetHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastEntry = history[history.length - 1];
            var r = lastEntry.results || {};
            var totalSpent = 1500 - (r.budgetRemaining || 0);
            var retention = r.retentionRate || 85;
            var fairness = r.fairnessScore || 35;
            var satisfaction = r.satisfactionScore || 45;
            var recovered = r.talentRecovered || 0;
            var composite = Math.round((retention * 0.25) + (fairness * 0.3) + (satisfaction * 0.25) + (recovered * 4));

            var performance = 'Needs Improvement';
            if (composite >= 75) performance = 'Excellent';
            else if (composite >= 55) performance = 'Good';
            else if (composite >= 40) performance = 'Adequate';

            var insights = [];
            if (retention >= 92) insights.push('Retention rate meets the strategic target of 92%+. Strong result.');
            else insights.push('Retention rate fell short of the 92% target. Compensation or communication may need more investment.');
            if (fairness >= 70) insights.push('PM system is perceived as fair and transparent by employees.');
            else insights.push('Fairness perception remains below target. Calibration processes may need strengthening.');
            if (recovered >= 2) insights.push('Successfully recovered ' + recovered + ' of 5 departed top performers.');
            else insights.push('Talent recovery was limited. Earlier and more aggressive counter-offers could help.');

            return {
                totalSpent: totalSpent,
                overallScore: composite,
                score: composite,
                retention: retention,
                fairness: fairness,
                satisfaction: satisfaction,
                talentRecovered: recovered,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (state.currentPeriod === 1 && state.domainState.diagnosisQuality < 40) {
                return window.mySimulation.t('hint_weak_diagnosis');
            }
            if (state.currentPeriod === 2 && state.domainState.budget < 400) {
                return window.mySimulation.t('hint_low_budget');
            }
            if (state.currentPeriod === 3 && state.domainState.talentRecovered === 0) {
                return window.mySimulation.t('hint_no_recovery');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.roundCost', label: 'Round Cost ($K)', i18nKey: 'col_cost', formatter: function(v) { return '$' + v.toLocaleString() + 'K'; } },
                { key: 'results.budgetRemaining', label: 'Budget Left ($K)', i18nKey: 'col_budget', formatter: function(v) { return '$' + v.toLocaleString() + 'K'; } },
                { key: 'results.retentionRate', label: 'Retention %', i18nKey: 'col_retention', formatter: function(v) { return v + '%'; } },
